cd /tmp && node -e '
const fs=require("fs");
let out=[];
for(let cp=0x20;cp<=0xFFFF;cp++){
  if(cp>=0xD800&&cp<=0xDFFF) continue;
  if(cp===0x0A||cp===0x0D) continue;
  out.push(String.fromCodePoint(cp)+".com");
}
fs.writeFileSync("/tmp/bmp.txt", out.join("\n")+"\n");
console.log(out.length);
'
